-- A automação "Conferir e corrigir DFDs × Centi" de fato UMA e com o diagrama ATUAL. A 0191 só renomeou: quem tinha mais de
-- uma "Corrigir DFDs divergentes pela Centi" ficou com duplicatas, e o diagrama seguiu o antigo (Filtrar genérico, Seleção
-- "não segue nenhum", Executar "Conferir 1 DFD" e Corrigir fora do subfluxo).
-- 1) Uma por pessoa: fica a de menor id do mesmo dono; a de dono definido sai quando há uma sem dono (que a pessoa também vê).
DELETE FROM `automacao_fluxos`
WHERE `nome` = 'Conferir e corrigir DFDs × Centi'
  AND (
    EXISTS (SELECT 1 FROM `automacao_fluxos` o WHERE o.`nome` = 'Conferir e corrigir DFDs × Centi' AND o.`id` < `automacao_fluxos`.`id` AND o.`criado_por` IS `automacao_fluxos`.`criado_por`)
    OR (`criado_por` IS NOT NULL AND EXISTS (SELECT 1 FROM `automacao_fluxos` o WHERE o.`nome` = 'Conferir e corrigir DFDs × Centi' AND o.`criado_por` IS NULL))
  )
  AND NOT EXISTS (
    SELECT 1 FROM `automacao_fluxos` o
    WHERE o.`id` <> `automacao_fluxos`.`id`
      AND (o.`grafo` LIKE '%"fluxoId":"' || `automacao_fluxos`.`id` || '"%' OR o.`grafo` LIKE '%"fluxoId":' || `automacao_fluxos`.`id` || ',%' OR o.`grafo` LIKE '%"fluxoId":' || `automacao_fluxos`.`id` || '}%')
  );
--> statement-breakpoint
