,"saida":"semMudanca","para":"ret1","entrada":"entrada"},{"de":"corr1","saida":"semMudanca","para":"err1","entrada":"entrada"}]}', u.`criado_por`, 0
FROM `automacao_fluxos` u
WHERE u.`nome` = 'Conferir e corrigir DFDs × Centi' AND NOT EXISTS (SELECT 1 FROM `automacao_fluxos` f WHERE f.`nome` = 'Conferir e corrigir 1 DFD × Centi' AND f.`criado_por` IS u.`criado_por`)
